:root {
  --color-bg: #ffffff;
  --color-bg-alt: #f3f1ec;
  --color-text: #22272e;
  --color-text-muted: #4a4f57;
  --color-primary-dark: #163a5f;
  --color-primary-darker: #0f2843;
  --color-accent: #b68a2e;
  --color-accent-on-dark: #e8c468;
  --color-border: #d9d4c8;
  --font-heading: Georgia, 'Times New Roman', serif;
  --font-body: Georgia, 'Times New Roman', serif;
  --space-xs: 0.5rem;
  --space-sm: 1rem;
  --space-md: 1.5rem;
  --space-lg: 2.5rem;
  --space-xl: 4rem;
  --radius: 0.4rem;
  --max-width: 75rem;
}

*, *::before, *::after { box-sizing: border-box; }

html { scroll-behavior: smooth; }

body {
  margin: 0;
  font-family: var(--font-body);
  color: var(--color-text);
  background: var(--color-bg);
  line-height: 1.6;
  font-size: 1rem;
}

h1, h2, h3, h4 {
  font-family: var(--font-heading);
  color: var(--color-primary-darker);
  line-height: 1.25;
  margin-top: 0;
}

p { margin-top: 0; }

a {
  color: var(--color-primary-dark);
  text-decoration: underline;
}

a:hover { color: var(--color-primary-darker); }

a:focus-visible,
button:focus-visible,
input:focus-visible,
textarea:focus-visible {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 1.25rem;
  width: 100%;
}

/* Header */
header {
  background: var(--color-primary-darker);
  color: var(--color-accent-on-dark);
  padding: var(--space-sm) 0;
}

.header-inner {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-sm);
}

.logo {
  font-family: Georgia, 'Times New Roman', serif;
  text-transform: uppercase;
  font-size: clamp(1.1rem, 1rem + 1vw, 1.3rem);
  letter-spacing: 0.2em;
  color: var(--color-accent-on-dark);
  text-decoration: none;
  border-top: 3px double var(--color-accent-on-dark);
  border-bottom: 3px double var(--color-accent-on-dark);
  padding: 0.3rem 0.6rem;
  display: inline-block;
  max-width: 100%;
}

.logo:hover { color: #ffffff; }

nav .nav-list {
  list-style: none;
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-md);
  margin: 0;
  padding: 0;
}

nav a {
  color: var(--color-accent-on-dark);
  text-decoration: none;
  font-weight: bold;
  padding: 0.4rem 0.2rem;
}

nav a:hover,
nav a:focus-visible {
  text-decoration: underline;
}

/* Main spacing */
main {
  display: block;
}

section {
  padding: var(--space-xl) 0;
}

section:nth-of-type(even) {
  background: var(--color-bg-alt);
}

/* Buttons */
.button,
button,
input[type="submit"] {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 44px;
  padding: 0.6rem 1.4rem;
  background: var(--color-primary-dark);
  color: #ffffff;
  border: none;
  border-radius: var(--radius);
  font-size: 1rem;
  font-weight: bold;
  text-decoration: none;
  cursor: pointer;
}

.button:hover,
button:hover,
input[type="submit"]:hover {
  background: var(--color-primary-darker);
}

/* Cards & grid */
.grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-lg);
}

.card {
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.card img {
  width: 100%;
  height: auto;
  display: block;
}

.card-body {
  padding: var(--space-md);
  display: flex;
  flex-direction: column;
  gap: var(--space-xs);
  flex: 1;
}

.price {
  font-size: 1.3rem;
  font-weight: bold;
  color: var(--color-primary-dark);
}

/* Forms */
form {
  display: grid;
  gap: var(--space-md);
  max-width: 40rem;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
}

label {
  font-weight: bold;
  color: var(--color-text);
}

input,
textarea,
select {
  min-height: 44px;
  padding: 0.5rem 0.7rem;
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  font-family: inherit;
  font-size: 1rem;
  background: #ffffff;
  color: var(--color-text);
}

textarea {
  min-height: 8rem;
  resize: vertical;
}

/* Footer */
footer {
  background: var(--color-primary-darker);
  color: #f2efe7;
  padding: var(--space-lg) 0;
}

.footer-inner p {
  margin: 0.3rem 0;
}

.footer-name {
  font-weight: bold;
  font-size: 1.1rem;
  color: var(--color-accent-on-dark);
}

.footer-copy {
  margin-top: var(--space-sm);
  color: #cfcabc;
  font-size: 0.9rem;
}

/* Mobile */
@media (max-width: 600px) {
  .header-inner {
    flex-direction: column;
    align-items: flex-start;
  }

  nav .nav-list {
    flex-direction: column;
    gap: var(--space-xs);
    width: 100%;
  }

  section {
    padding: var(--space-lg) 0;
  }

  .logo {
    font-size: 1.05rem;
    letter-spacing: 0.12em;
  }
}

/* Desktop */
@media (min-width: 601px) {
  .grid-3 {
    grid-template-columns: repeat(3, 1fr);
  }

  .grid-2 {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
}

